"""Launch one supervised diagnostic/pilot JVM; preserve every attempt and its immutable inputs."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import time

PHASE = Path(__file__).resolve().parent
ROOT = PHASE.parents[1]
JDK = Path('/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8')


def sha(path):
    with path.open('rb') as f:
        return hashlib.file_digest(f, 'sha256').hexdigest()


def identity(path):
    return {str(p.relative_to(path)): sha(p) for p in sorted(path.rglob('*')) if p.is_file()} if path.is_dir() else sha(path)


def save(path, obj):
    with path.open('x') as f:
        json.dump(obj, f, indent=2, sort_keys=True)
        f.write('\n')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--classpath', type=Path, required=True)
    parser.add_argument('--main', required=True)
    parser.add_argument('--property', action='append', default=[])
    parser.add_argument('--heap-mib', type=int, default=1024)
    parser.add_argument('--slot-granted', action='store_true')
    parser.add_argument('arguments', nargs=argparse.REMAINDER)
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS', 'LD_PRELOAD'):
        if os.environ.get(key):
            raise ValueError('Unexpected runtime environment: ' + key)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    cp_file = args.classpath.resolve(strict=True)
    cp = cp_file.read_text().strip()
    paths = [Path(p).resolve(strict=True) for p in cp.split(os.pathsep)]
    inputs = {str(p): identity(p) for p in paths}
    inputs.update({str(p): identity(p) for p in [JDK / 'bin/java', JDK / 'release', JDK / 'lib/modules', cp_file]})
    save(output / 'inputs.json', inputs)
    arguments = args.arguments[1:] if args.arguments[:1] == ['--'] else args.arguments
    argv = [str(JDK / 'bin/java'), f'-Xms{args.heap_mib}m', f'-Xmx{args.heap_mib}m', '-XX:+UseG1GC',
            '-XX:ObjectAlignmentInBytes=8', '-XX:+UseCompressedOops', '-XX:+UseCompressedClassPointers',
            '-Xlog:gc:file=' + str(output / 'gc.log') + ':uptime,level,tags',
            *['-D' + value for value in args.property], '-cp', cp, args.main, *arguments]
    started = time.time_ns()
    save(output / 'command.json', {'argv': argv, 'cwd': str(ROOT), 'startedEpochNs': started,
                                   'purpose': 'diagnostic-or-qualification-not-comparison'})
    with (output / 'stdout.jsonl').open('xb') as stdout, (output / 'stderr.log').open('xb') as stderr:
        process = subprocess.Popen(argv, cwd=ROOT, stdout=stdout, stderr=stderr, start_new_session=True)
        deadline = time.monotonic() + 300
        timed_out = False
        while True:
            try:
                code = process.wait(timeout=min(30, max(0.001, deadline - time.monotonic())))
                break
            except subprocess.TimeoutExpired:
                if time.monotonic() >= deadline:
                    timed_out = True
                    os.killpg(process.pid, signal.SIGTERM)
                    try:
                        code = process.wait(timeout=5)
                    except subprocess.TimeoutExpired:
                        os.killpg(process.pid, signal.SIGKILL)
                        code = process.wait(timeout=5)
                    break
                print('JVM running; complete output is preserved.', flush=True)
    same = all(identity(Path(p)) == value for p, value in inputs.items())
    receipt = {'exitCode': code, 'timedOut': timed_out, 'inputsUnchanged': same,
               'startedEpochNs': started, 'finishedEpochNs': time.time_ns(),
               'rawHashes': {p.name: sha(p) for p in output.iterdir() if p.is_file()},
               'comparisonSample': False}
    save(output / 'process.json', receipt)
    print(json.dumps({'output': str(output), 'exitCode': code, 'inputsUnchanged': same,
                      'seconds': (receipt['finishedEpochNs'] - started) / 1e9}), flush=True)
    if code or timed_out or not same:
        raise SystemExit(code or 1)


if __name__ == '__main__':
    main()
